def load() -> pd.DataFrame:
    import glob
    import os
    import pandas as pd

    pattern = 'data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*.csv'
    paths = sorted(glob.glob(pattern))
    if not paths:
        raise FileNotFoundError(f'No files matched pattern: {pattern}')

    return pd.DataFrame({'path': paths, 'filename': [os.path.basename(p) for p in paths]})

def process(newEnglandStates) -> pd.DataFrame:
    import pandas as pd

    # Build a normalized lookup set for matching against the identity theft 'state' column
    states = (
        newEnglandStates[['Name']]
        .dropna()
        .assign(state=lambda d: d['Name'].astype(str).str.strip())
    )

    return states[['state']].drop_duplicates().sort_values('state').reset_index(drop=True)
